package com.tracksphere.domain.model; import jakarta.persistence.*; import lombok.*; import java.time.Instant; import java.util.UUID;
@Entity @Table(name="audit_logs") @Getter @NoArgsConstructor(access=AccessLevel.PROTECTED) public class AuditLog { @Id private UUID id; @Column(name="actor_id") private UUID actorId; @Column(nullable=false,length=120) private String action; @Column(length=180) private String target; @Column(length=1000) private String details; @Column(name="created_at",nullable=false) private Instant createdAt; public AuditLog(UUID actorId,String action,String target,String details){id=UUID.randomUUID();this.actorId=actorId;this.action=action;this.target=target;this.details=details;createdAt=Instant.now();} }
